import assert from 'node:assert/strict';
const replicas={A:1,B:0,C:0};
const read=names=>Math.max(...names.map(name=>replicas[name]));
const observed=[read(['A','B']),read(['B','C'])];
assert.deepEqual(observed,[1,0]);
const validSerialReads=[];
for(let position=0;position<=2;position++){const order=['X','Y'];order.splice(position,0,'W');let value=0;const result=[];for(const operation of order){if(operation==='W')value=1;else result.push(value);}validSerialReads.push(result);}
assert(!validSerialReads.some(result=>JSON.stringify(result)===JSON.stringify(observed)));
replicas.B=Math.max(replicas.B,replicas.A);
const withReadPropagation=[read(['A','B']),read(['B','C'])];
assert.deepEqual(withReadPropagation,[1,1]);
assert(validSerialReads.some(result=>JSON.stringify(result)===JSON.stringify(withReadPropagation)));
const members=[['a','A',false],['b','A',false],['c','B',false],['d','C',false],['e','C',true]];
function availability(list){const voters=list.filter(member=>!member[2]);const quorum=Math.floor(voters.length/2)+1;return {voters:voters.length,quorum,losses:Object.fromEntries(['A','B','C'].map(zone=>{const survivors=voters.filter(member=>member[1]!==zone).length;return [zone,{survivors,canFormQuorum:survivors>=quorum}];}))};}
const before=availability(members);const after=availability(members.map(member=>[member[0],member[1],false]));
assert.equal(before.voters,4);assert.equal(before.quorum,3);assert.equal(before.losses.A.canFormQuorum,false);
assert.equal(after.voters,5);assert.equal(after.quorum,3);assert(Object.values(after.losses).every(value=>value.canFormQuorum));
console.log(JSON.stringify({observed,validSerialReads,withReadPropagation,before,after},null,2));

